#!/usr/bin/env python3
# spend.py <since-epoch> <file-or-dir>...: tokens written (input + cache creation) and read, per transcript, deduplicated by message id
# the coordinating session's own transcript (fe616d40) is left out; agents: <session-dir>/subagents/*.jsonl or a task output file; claude -p runs: the project directory
import json, os, sys, glob
since=float(sys.argv[1]); files=[]
for a in sys.argv[2:]:
    files += [a] if os.path.isfile(a) else glob.glob(os.path.join(a,'*.jsonl'))
tw=tr=0; n=0
for f in sorted(set(files)):
    if os.path.getmtime(f) < since or os.path.basename(f).startswith("fe616d40"): continue
    seen={}; 
    for line in open(f, errors='replace'):
        try: r=json.loads(line)
        except Exception: continue
        m=r.get('message') if isinstance(r.get('message'),dict) else None
        if not m or 'usage' not in m: continue
        seen[m.get('id') or id(m)]=m['usage']
    w=sum(u.get('input_tokens',0)+u.get('cache_creation_input_tokens',0) for u in seen.values())
    rd=sum(u.get('cache_read_input_tokens',0) for u in seen.values())
    if seen: n+=1; tw+=w; tr+=rd; print(f"{os.path.basename(f)[:40]:40} calls={len(seen):4} written={w/1e3:8.1f}K read={rd/1e6:6.2f}M")
print(f"TOTAL files={n} written={tw/1e6:.2f}M read={tr/1e6:.2f}M")

    c = r.reproducer.strip().strip('`')
    if c in ('none', ''):
        return 'none', c
    c = re.sub(r':\d[\d,-]*$', '', c)
    p = c if os.path.exists(os.path.join(ROOT, c)) else None
    if p is None and '/' not in c:
        try:
            p = lin.test_path(c)
        except L.LedgerError:
            p = None
    if p is None:
        return 'missing', c
    if p.startswith('explorations/'):
        return 'probe', p
    seg = p.split('/')
    if seg[0] == 'ProjectFortress' and len(seg) > 1 and (seg[1] == 'tests' or seg[1].endswith('_tests') or seg[1] in L.TEST_FOLDERS_EXTRA):
        x = 'XXX' in os.path.basename(p)
        if not x and p.endswith('.test'):
            x = any(l.startswith('tests=') and 'XXX' in l for l in open(os.path.join(ROOT, p), errors='replace'))
        if not x and p.endswith('.fss'):
            # a Link pair: XXX<Name>.test beside it
            d, b = os.path.split(p)
            x = os.path.exists(os.path.join(ROOT, d, 'XXX' + b[:-4] + '.test'))
        return ('xxx' if x else 'plain'), p
    return 'other-path', p
tab = collections.Counter()
with open(os.path.join(HERE, '..', 'guards.tsv'), 'w') as f:
    f.write('row\tstatus\tera\tkind\tspec_silent\treproducer\n')
    for r in led.rows:
        if r.status_word not in OPEN:
            continue
        k, p = kind(r)
        tab[(era(r.num), k)] += 1
        tab[('all', k)] += 1
        f.write('%d\t%s\t%s\t%s\t%s\t%s\n' % (r.num, r.status_word, era(r.num), k, r.spec.strip() == 'silent', p))
kinds = ['xxx', 'plain', 'probe', 'other-path', 'none', 'missing']
print('era\t' + '\t'.join(kinds) + '\ttotal')
for e in ('A', 'B', 'C', 'all'):
    row = [tab[(e, k)] for k in kinds]
    print(e + '\t' + '\t'.join(map(str, row)) + '\t%d' % sum(row))

